        "items": [
          {
            "type": 1,
            "content": {
              "json": "## Azure AI estate - issue overview\r\n\r\nCovers **Azure OpenAI**, **Microsoft Foundry (AI Services)**, **Foundry projects**,\r\nand **AI Hub / AI Project** workspaces across every selected subscription.\r\n\r\nAccount and workspace findings come from **Azure Resource Graph**. Model\r\ndeployments are *not* indexed by Resource Graph at all, so the **Model deployments**\r\ntab reads them from the Azure Resource Manager control plane instead. See\r\n**About the data** for the measured details."
            },
            "name": "ovHead"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.cognitiveservices/accounts'\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend acctKind   = tostring(kind)\n| extend isModelHost = (acctKind in~ ('OpenAI','AIServices'))\n| extend skuName    = tostring(sku.name)\n| extend identityType = tostring(identity.type)\n| extend pna        = tostring(properties.publicNetworkAccess)\n| extend localAuthDisabled = tobool(properties.disableLocalAuth)\n| extend subdomain  = tostring(properties.customSubDomainName)\n| extend restrictOutbound = tobool(properties.restrictOutboundNetworkAccess)\n| extend netDefault = tostring(properties.networkAcls.defaultAction)\n| extend ipRuleCount = toint(array_length(todynamic(properties.networkAcls.ipRules)))\n| extend vnetRuleCount = toint(array_length(todynamic(properties.networkAcls.virtualNetworkRules)))\n| extend cmkSource  = tostring(properties.encryption.keySource)\n| extend allowProjectMgmt = tobool(properties.allowProjectManagement)\n| extend state      = tostring(properties.provisioningState)\n| extend created    = todatetime(properties.dateCreated)\n| extend endpoint   = tostring(properties.endpoint)\n| extend isMigrated = tobool(properties.isMigrated)\n| extend peCount    = toint(array_length(todynamic(properties.privateEndpointConnections)))\n| extend KindLabel  = case(\n      acctKind =~ 'OpenAI',     'Azure OpenAI',\n      acctKind =~ 'AIServices', 'Microsoft Foundry (AI Services)',\n      acctKind =~ 'CognitiveServices', 'Cognitive Services (multi-service)',\n      acctKind)\n| extend IssueList = array_concat(\n    iff(localAuthDisabled != true,                      pack_array('API key (local) auth enabled - prefer Entra ID'), dynamic([])),\n    iff(pna =~ 'Enabled' and peCount == 0,              pack_array('Public network access with no private endpoint'), dynamic([])),\n    iff(pna =~ 'Enabled' and netDefault !~ 'Deny',      pack_array('Network ACLs allow all traffic'), dynamic([])),\n    iff(isempty(identityType) or identityType =~ 'None', pack_array('No managed identity'), dynamic([])),\n    iff(isModelHost and isempty(subdomain),             pack_array('No custom subdomain - Entra ID auth unavailable'), dynamic([])),\n    iff(isempty(cmkSource) or cmkSource =~ 'Microsoft.CognitiveServices', pack_array('Microsoft-managed keys (no CMK)'), dynamic([])),\n    iff(isModelHost and restrictOutbound != true,       pack_array('Outbound network access unrestricted'), dynamic([])),\n    iff(state !~ 'Succeeded',                           pack_array(strcat('Provisioning state: ', state)), dynamic([]))\n  )\n| extend IssueCount = array_length(IssueList)\n| extend Issues     = strcat_array(IssueList, ' | ')\n| extend Severity = case(\n      IssueCount >= 6, 'Critical',\n      IssueCount >= 4, 'High',\n      IssueCount >= 2, 'Medium',\n      IssueCount >= 1, 'Low',\n                       'Healthy')\n| extend SeverityRank = case(Severity == 'Critical', 0, Severity == 'High', 1, Severity == 'Medium', 2, Severity == 'Low', 3, 4)\n| summarize\n    ModelHosts  = countif(isModelHost),\n    OpenAIAcct  = countif(acctKind =~ 'OpenAI'),\n    FoundryAcct = countif(acctKind =~ 'AIServices'),\n    OtherAI     = countif(isModelHost == false),\n    AtRisk      = countif(IssueCount > 0),\n    CritHigh    = countif(Severity in ('Critical','High')),\n    KeyAuth     = countif(localAuthDisabled != true),\n    OpenNet     = countif(pna =~ 'Enabled' and peCount == 0)\n| extend Tiles = pack_array(\n    pack('Metric', 'Model-hosting accounts',   'Value', ModelHosts,  'Rank', 1),\n    pack('Metric', 'Azure OpenAI',             'Value', OpenAIAcct,  'Rank', 2),\n    pack('Metric', 'Microsoft Foundry',        'Value', FoundryAcct, 'Rank', 3),\n    pack('Metric', 'Other AI services',        'Value', OtherAI,     'Rank', 4),\n    pack('Metric', 'Accounts with findings',   'Value', AtRisk,      'Rank', 5),\n    pack('Metric', 'Critical or high',         'Value', CritHigh,    'Rank', 6),\n    pack('Metric', 'API key auth enabled',     'Value', KeyAuth,     'Rank', 7),\n    pack('Metric', 'Public, no private endpoint', 'Value', OpenNet,  'Rank', 8))\n| mv-expand Tiles\n| project Metric = tostring(Tiles.Metric), Value = toint(Tiles.Value), Rank = toint(Tiles.Rank)\n| order by Rank asc",
              "size": 3,
              "title": "AI estate summary",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "tiles",
              "tileSettings": {
                "titleContent": {
                  "columnMatch": "Metric",
                  "formatter": 1
                },
                "leftContent": {
                  "columnMatch": "Value",
