          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "advisorresources\n| where type =~ 'microsoft.advisor/recommendations'\n| extend targetId = tolower(tostring(properties.resourceMetadata.resourceId))\n| join kind=inner (\n    resources\n    | where type =~ 'microsoft.cognitiveservices/accounts'\n       or type =~ 'microsoft.machinelearningservices/workspaces'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | project targetId = tolower(id), rName = name, rRg = resourceGroup, rType = type\n  ) on targetId\n| project\n    Resource = rName,\n    ['Resource group'] = rRg,\n    Category = tostring(properties.category),\n    Impact = tostring(properties.impact),\n    Problem = tostring(properties.shortDescription.problem),\n    Solution = tostring(properties.shortDescription.solution),\n    ResourceId = targetId\n| order by Impact asc, Resource asc",
